# catch data from Commercial fishery
path_data_cap <- "data/capture_Agg.rds"
# biometry data from Commercial fishery
path_data_bio <- "data/biometrie.rds"
# path to the station
path_data_station <- "data/Station.rds"
# path to the directory containing the three tif files generated by bathyKER
path_rast_bathy <- "data/carte"

# outputs paths
output_df <- "outputs/df/"
output_carte <- "outputs/carte/"
output_plot <- "outputs/plot/"

SavePlots = TRUE

# 2. make the grid to project prediction -------------------------------------

# resolution of the grid (in meters -> in this example each cells are 1000m x 1000m)
res = 1000

#method of resampling for the function terra::resample to match the grid with the map

resampling_method = "bilinear"



# 3. sdmTMB ---------------------------------------------------------------

#If TRUE the total catch and nb of hook will be divide equally in all the point along the the longline
repartition = FALSE


#The filter apply on the data frame
#cond_prof = variation entre la profondeur min et max
#cond_dit = variation de distance comaparé à la distance théorique
#cond_taille = varitaiton entre taille min et max 

filtres_actifs <- c("cond_prof", "cond_dist")

#Model sdmTMB
#Variable reponse du modèle
var_reponse <- "CPUE"

#Variable explicative du modèle
var_explicative <- "s(prof_bathy) + slope + tps_h"

#formule complète du modèle
formula_sdm <- as.formula(paste(var_reponse, "~", var_explicative))

formula_name = paste0(var_reponse, "~",var_explicative)


distrib_family <- Gamma(link = "log")

family_name <- paste0(distrib_family$family,"~", distrib_family$link)

spatial_var <- "on"


#number of simulation for dharma_residual
number_sim = 500


# 4. Parameter of the grid ------------------------------------------------
#number of hook for each cell
nb_ham = 380

#Filter to keep the cells with depth superior at the values
min_depth = 500